inputs = ['ghdi', 'ux', 'gjchg', 'zu', 'byyu']
outputs = ['gcihdi', 'ufz', 'hfzichgci', 'zu', 'byyu']

# Analyze pair by pair
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{out}'")

    # Find differences
    if inp != out:
        min_len = min(len(inp), len(out))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break

        if diff_pos != -1:
            print(f"  First difference at position {diff_pos}")
            print(f"  Input char: '{inp[diff_pos]}'")
            print(f"  Output char: '{out[diff_pos]}'")

            # Try to see if we can identify patterns
            if len(inp) > diff_pos + 1 and len(out) > diff_pos + 1:
                print(f"  Next chars: '{inp[diff_pos+1]}' -> '{out[diff_pos+1]}'")

        print(f"  Length change: {len(out) - len(inp)}")
    else:
        print("  No change")

